mapper.select:
select p_name,o_id,c_name,p_amount,o_date,o_state from order_info_all where c_name=#{client_name} and o_state='缺货'
AND o_date>#{startdate}
AND o_date<finishdate

select client_info.c_name,c_id,c_mTele,c_identity,new.total_sum p_amount from client_info,(SELECT c_name,SUM(p_amount) AS total_sum FROM order_info_all WHERE c_name = #{client_name}) new where client_info.c_name=new.c_name
AND o_date>#{startdate}
AND o_date<finishdate
